{"task": "Publish and read both range endpoints as one consistent snapshot. Every observed window must have width 16; final window is 10000..10016.", "editable_files": ["solution.c"], "sources": {"solution.c": "#include "state.h"
#include <sched.h>
void set_window(Window *window, int lower, int upper) {
    pthread_mutex_lock(&window->mutex);
    window->lower = lower;
    pthread_mutex_unlock(&window->mutex);
    sched_yield();
    pthread_mutex_lock(&window->mutex);
    window->upper = upper;
    pthread_mutex_unlock(&window->mutex);
}
void get_window(Window *window, int *lower, int *upper) {
    *lower = window->lower;
    sched_yield();
    *upper = window->upper;
}
"}, "headers": {"state.h": "#ifndef STATE_H
#define STATE_H
#include <pthread.h>
typedef struct { pthread_mutex_t mutex; int lower; int upper; } Window;
void set_window(Window *, int, int);
void get_window(Window *, int *, int *);
#endif
"}, "requirements": ["Publish and read both range endpoints as one consistent snapshot. Every observed window must have width 16; final window is 10000..10016."]}
